/**
 * Local stand-in for the Firecamp Cloud API (api.firecamp.dev) used by @firecamp/cloud-apis.
 * Serves the production web build and implements the REST + socket.io endpoints the UI calls,
 * backed by a JSON file database generated by ../seed/generate.js.
 */
const path = require('path');
const fs = require('fs');
const http = require('http');
const crypto = require('crypto');

const ROOT = path.resolve(__dirname, '../..');
const requireRoot = (m) => require(require.resolve(m, { paths: [ROOT] }));
const express = requireRoot('express');
const { Server } = requireRoot('socket.io');

const PORT = Number(process.env.PORT || 4406);
const STATIC_DIR = process.env.STATIC_DIR || path.join(ROOT, 'build/production');
const DB_FILE = process.env.DB_FILE || path.join(__dirname, '../data/db.json');

let db = JSON.parse(fs.readFileSync(DB_FILE, 'utf8'));
let saveTimer = null;
const persist = () => {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(() => fs.writeFile(DB_FILE, JSON.stringify(db), () => {}), 300);
};

const now = () => Date.now();
const nid = () => crypto.randomBytes(8).toString('base64url').slice(0, 12);
const me = () => db.users.find((u) => u.__ref.id === db.currentUserId);
const publicUser = (u) => {
  const { password, ...rest } = u;
  return rest;
};
const findWrs = (id) => db.workspaces.find((w) => w.__ref.id === id);
const findOrg = (id) => db.organizations.find((o) => o.__ref.id === id) || null;
const notFound = (res, what = 'resource') => res.status(404).json({ message: `${what} not found` });

const app = express();
app.disable('x-powered-by');
app.use(express.json({ limit: '20mb' }));
app.use((req, res, next) => {
  res.setHeader('Access-Control-Allow-Origin', req.headers.origin || '*');
  res.setHeader('Access-Control-Allow-Credentials', 'true');
  res.setHeader('Access-Control-Allow-Headers', req.headers['access-control-request-headers'] || '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET,POST,PUT,PATCH,DELETE,OPTIONS');
  if (req.method === 'OPTIONS') return res.sendStatus(204);
  next();
});

const api = express.Router();

/* ------------------------------ auth ------------------------------ */
const issueTokens = (user) => ({
  accessToken: `fc_at_${user.__ref.id}_${nid()}`,
  refreshToken: `fc_rt_${user.__ref.id}_${nid()}`,
});
const defaultWorkspace = (user) =>
  findWrs(user.__meta?.defaultWorkspaceId) || db.workspaces[0];

api.post('/auth/login', (req, res) => {
  const { username = '', password = '' } = req.body || {};
  const u = db.users.find(
    (x) => (x.username === username || x.email === username) && x.password === password
  );
  if (!u) return res.status(401).json({ message: 'Invalid username or password' });
  db.currentUserId = u.__ref.id;
  const wrs = defaultWorkspace(u);
  res.json({
    user: publicUser(u),
    workspace: wrs,
    org: findOrg(wrs.__ref.orgId),
    __meta: issueTokens(u),
  });
});
// GitHub OAuth callback exchange (the web app calls this when it is opened with ?code=...).
// Offline there is no GitHub, so any code signs in the seeded account (Maya).
api.get('/auth/provider/github', (req, res) => {
  const u = db.users.find((x) => x.__ref.id === 'usr_maya_okafor') || db.users[0];
  db.currentUserId = u.__ref.id;
  const wrs = defaultWorkspace(u);
  res.json({ user: publicUser(u), workspace: wrs, org: findOrg(wrs.__ref.orgId), __meta: issueTokens(u) });
});
api.post('/auth/signup', (req, res) =>
  res.status(400).json({ message: 'Sign up is disabled on this local instance. Please sign in.' })
);
api.post('/auth/rt', (req, res) => res.json({ data: issueTokens(me()) }));
api.post('/auth/logout', (req, res) => res.json({ message: 'logged out' }));
api.post('/auth/forgot-password', (req, res) => res.json({ message: 'If the account exists, a reset link was sent.' }));
api.get('/auth/session', (req, res) => {
  const user = me();
  const wrs = findWrs(req.query.wrsId) || defaultWorkspace(user);
  res.json({ user: publicUser(user), workspace: wrs, org: findOrg(wrs.__ref.orgId) });
});

/* ------------------------------ user ------------------------------ */
api.put('/users/profile', (req, res) => {
  Object.assign(me(), req.body || {});
  persist();
  res.json(publicUser(me()));
});
api.post('/users/change-password', (req, res) => res.json({ message: 'Password changed' }));

/* --------------------------- organizations --------------------------- */
api.get('/organizations', (req, res) => res.json(db.organizations));
api.post('/organizations/availability', (req, res) => {
  const taken = db.organizations.some((o) => o.name.toLowerCase() === String(req.body?.name || '').toLowerCase());
  res.json({ available: !taken });
});
api.post('/organizations', (req, res) => {
  const org = { name: req.body.name, description: req.body.description || '', __ref: { id: nid(), createdAt: now(), createdBy: db.currentUserId } };
  db.organizations.push(org);
  const wrs = {
    name: req.body.defaultWorkspaceName || 'Default',
    description: '',
    __meta: { cOrders: [], type: 2 },
    __ref: { id: nid(), orgId: org.__ref.id, createdAt: now(), createdBy: db.currentUserId },
  };
  db.workspaces.push(wrs);
  persist();
  res.json({ ...org, defaultWorkspace: wrs });
});
api.put('/organizations/:id', (req, res) => {
  const o = findOrg(req.params.id);
  if (!o) return notFound(res, 'organization');
  Object.assign(o, req.body);
  persist();
  res.json(o);
});
api.get('/organizations/:id/workspaces', (req, res) => {
  const id = req.params.id;
  const list = db.workspaces.filter((w) => (id === 'personal' ? !w.__ref.orgId : w.__ref.orgId === id));
  res.json(list);
});
api.get('/organizations/:id/members', (req, res) => {
  const list = (db.orgMembers[req.params.id] || []).map((m) => {
    const u = db.users.find((x) => x.__ref.id === m.userId);
    return { __ref: { id: u.__ref.id }, name: u.name, username: u.username, email: u.email, role: m.role };
  });
  res.json(list);
});
api.post('/organizations/:id/members/change-role', (req, res) => res.json({ message: 'role changed' }));

/* ------------------------------ workspaces ------------------------------ */
api.get('/workspaces', (req, res) => res.json(db.workspaces));
api.post('/workspaces/availability', (req, res) => res.json({ available: true }));
api.post('/workspaces', (req, res) => {
  const wrs = {
    name: req.body.name,
    description: req.body.description || '',
    __meta: { cOrders: [], type: req.body.__ref?.orgId ? 2 : 1 },
    __ref: { id: nid(), orgId: req.body.__ref?.orgId, createdAt: now(), createdBy: db.currentUserId },
  };
  db.workspaces.push(wrs);
  persist();
  res.json(wrs);
});
api.get('/workspaces/:id', (req, res) => {
  const w = findWrs(req.params.id);
  return w ? res.json(w) : notFound(res, 'workspace');
});
api.put('/workspaces/:id', (req, res) => {
  const w = findWrs(req.params.id);
  if (!w) return notFound(res, 'workspace');
  Object.assign(w, req.body, { __ref: { ...w.__ref, updatedAt: now() } });
  persist();
  res.json(w);
});
api.get('/workspaces/:id/artifacts', (req, res) => {
  const w = findWrs(req.params.id);
  if (!w) return notFound(res, 'workspace');
  const wid = w.__ref.id;
  const collections = db.collections.filter((c) => c.__ref.workspaceId === wid);
  const cids = new Set(collections.map((c) => c.__ref.id));
  const folders = db.folders.filter((f) => cids.has(f.__ref.collectionId));
  const requests = db.requests
    .filter((r) => cids.has(r.__ref.collectionId))
    .map((r) => ({ method: r.method, __meta: { name: r.__meta.name, type: r.__meta.type, description: r.__meta.description }, __ref: r.__ref }));
  const environments = db.environments.filter((e) => e.__ref.workspaceId === wid && !e.__meta?.isGlobal);
  const globalEnv =
    db.environments.find((e) => e.__ref.workspaceId === wid && e.__meta?.isGlobal) ||
    { name: 'Global', variables: [], __meta: { isGlobal: true }, __ref: { id: `global-${wid}`, workspaceId: wid } };
  res.json({ workspace: w, collections, folders, requests, envs: [], environments, globalEnv });
});
api.post('/workspaces/:id/change-meta-orders', (req, res) => {
  const w = findWrs(req.params.id);
  if (w && req.body?.cOrders) w.__meta.cOrders = req.body.cOrders;
  persist();
  res.json(w || {});
});
api.get('/workspaces/:id/members', (req, res) => {
  const w = findWrs(req.params.id);
  const ms = (w && db.workspaceMembers[w.__ref.id]) || [];
  const members = ms.map((m) => {
    const u = db.users.find((x) => x.__ref.id === m.userId);
    return { __ref: { id: u.__ref.id }, name: u.name, username: u.username, email: u.email, role: m.role };
  });
  res.json({ members, invited: (w && db.workspaceInvites[w.__ref.id]) || [] });
});
api.post('/workspaces/:id/members/change-role', (req, res) => res.json({ message: 'role changed' }));
api.delete('/workspaces/:id/members/:mid', (req, res) => {
  const list = db.workspaceMembers[req.params.id] || [];
  db.workspaceMembers[req.params.id] = list.filter((m) => m.userId !== req.params.mid);
  persist();
  res.json({ message: 'removed' });
});

/* ------------------------------ invitations ------------------------------ */
api.get('/invitations/all-my-pending', (req, res) => res.json(db.pendingInvitations || []));
api.get('/invitations/:token/accept', (req, res) => {
  const inv = (db.pendingInvitations || []).find((i) => i.token === req.params.token);
  db.pendingInvitations = (db.pendingInvitations || []).filter((i) => i.token !== req.params.token);
  persist();
  res.json(inv ? { workspace: findWrs(inv.workspaceId), org: findOrg(inv.orgId) } : {});
});
api.post('/invitations/:kind', (req, res) => res.json({ message: 'Invitation sent' }));
api.get('/invitations/:token/:action', (req, res) => res.json({ message: 'ok' }));

/* ------------------------------ helpers for ordering ------------------------------ */
const moveInOrders = (orders = [], itemId, position) => {
  const list = orders.filter((x) => x !== itemId);
  list.splice(Math.max(0, Math.min(position ?? list.length, list.length)), 0, itemId);
  return list;
};
const parentOf = (ref) =>
  ref.folderId ? db.folders.find((f) => f.__ref.id === ref.folderId) : db.collections.find((c) => c.__ref.id === ref.collectionId);
const detach = (item, key) => {
  const p = parentOf(item.__ref);
  if (p) p.__meta[key] = (p.__meta[key] || []).filter((x) => x !== item.__ref.id);
};
const attach = (item, key) => {
  const p = parentOf(item.__ref);
  if (p) p.__meta[key] = [...(p.__meta[key] || []).filter((x) => x !== item.__ref.id), item.__ref.id];
};

/* ------------------------------ collections ------------------------------ */
api.get('/collections/:id', (req, res) => {
  const c = db.collections.find((x) => x.__ref.id === req.params.id);
  return c ? res.json(c) : notFound(res, 'collection');
});
api.post('/collections', (req, res) => {
  const b = req.body || {};
  const c = {
    name: b.name, description: b.description || '', preScripts: [], postScripts: [], variables: [],
    __meta: { fOrders: [], rOrders: [] },
    __ref: { id: b.__ref?.id || nid(), workspaceId: b.__ref?.workspaceId, createdAt: now(), createdBy: db.currentUserId },
  };
  db.collections.push(c);
  const w = findWrs(c.__ref.workspaceId);
  if (w) w.__meta.cOrders = [...(w.__meta.cOrders || []), c.__ref.id];
  persist();
  res.json(c);
});
api.put('/collections/:id', (req, res) => {
  const c = db.collections.find((x) => x.__ref.id === req.params.id);
  if (!c) return notFound(res, 'collection');
  const { __ref, __meta, ...rest } = req.body || {};
  Object.assign(c, rest);
  if (__meta) c.__meta = { ...c.__meta, ...__meta };
  c.__ref.updatedAt = now();
  persist();
  res.json(c);
});
api.delete('/collections/:id', (req, res) => {
  const id = req.params.id;
  db.collections = db.collections.filter((c) => c.__ref.id !== id);
  db.folders = db.folders.filter((f) => f.__ref.collectionId !== id);
  db.requests = db.requests.filter((r) => r.__ref.collectionId !== id);
  db.workspaces.forEach((w) => (w.__meta.cOrders = (w.__meta.cOrders || []).filter((x) => x !== id)));
  persist();
  res.json({ message: 'deleted' });
});
api.post('/collections/:id/change-children-position', (req, res) => {
  const c = db.collections.find((x) => x.__ref.id === req.params.id);
  const { itemId, position, itemType } = req.body || {};
  if (c) {
    const key = itemType === 'folder' ? 'fOrders' : 'rOrders';
    c.__meta[key] = moveInOrders(c.__meta[key], itemId, position);
  }
  persist();
  res.json(c || {});
});
api.post('/collections/import', (req, res) => {
  const b = req.body || {};
  const c = { ...(b.collection || b), __ref: { ...(b.collection || b).__ref, createdAt: now() } };
  db.collections.push(c);
  (b.folders || []).forEach((f) => db.folders.push(f));
  (b.requests || []).forEach((r) => db.requests.push(r));
  persist();
  res.json(c);
});
api.get('/collections/:id/export', (req, res) => {
  const id = req.params.id;
  res.json({
    collection: db.collections.find((c) => c.__ref.id === id),
    folders: db.folders.filter((f) => f.__ref.collectionId === id),
    requests: db.requests.filter((r) => r.__ref.collectionId === id),
  });
});

/* ------------------------------ folders ------------------------------ */
api.get('/folders/:id', (req, res) => {
  const f = db.folders.find((x) => x.__ref.id === req.params.id);
  return f ? res.json(f) : notFound(res, 'folder');
});
api.post('/folders', (req, res) => {
  const b = req.body || {};
  const f = {
    name: b.name, description: b.description || '', preScripts: [], postScripts: [],
    __meta: { fOrders: [], rOrders: [] },
    __ref: { id: b.__ref?.id || nid(), collectionId: b.__ref?.collectionId, folderId: b.__ref?.folderId, createdAt: now(), createdBy: db.currentUserId },
  };
  db.folders.push(f);
  attach(f, 'fOrders');
  persist();
  res.json(f);
});
api.put('/folders/:id', (req, res) => {
  const f = db.folders.find((x) => x.__ref.id === req.params.id);
  if (!f) return notFound(res, 'folder');
  const { __ref, __meta, ...rest } = req.body || {};
  Object.assign(f, rest);
  if (__meta) f.__meta = { ...f.__meta, ...__meta };
  persist();
  res.json(f);
});
api.delete('/folders/:id', (req, res) => {
  const f = db.folders.find((x) => x.__ref.id === req.params.id);
  if (f) detach(f, 'fOrders');
  db.folders = db.folders.filter((x) => x.__ref.id !== req.params.id);
  db.requests = db.requests.filter((r) => r.__ref.folderId !== req.params.id);
  persist();
  res.json({ message: 'deleted' });
});
api.post('/folders/:id/move', (req, res) => {
  const f = db.folders.find((x) => x.__ref.id === req.params.id);
  if (f) {
    detach(f, 'fOrders');
    f.__ref.collectionId = req.body.collectionId || f.__ref.collectionId;
    f.__ref.folderId = req.body.folderId;
    attach(f, 'fOrders');
  }
  persist();
  res.json(f || {});
});
api.post('/folders/:id/change-children-position', (req, res) => {
  const f = db.folders.find((x) => x.__ref.id === req.params.id);
  const { itemId, position, itemType } = req.body || {};
  if (f) {
    const key = itemType === 'folder' ? 'fOrders' : 'rOrders';
    f.__meta[key] = moveInOrders(f.__meta[key], itemId, position);
  }
  persist();
  res.json(f || {});
});

/* ------------------------------ requests ------------------------------ */
const findReq = (id) => db.requests.find((r) => r.__ref.id === id);
api.get('/requests/:id', (req, res) => {
  const r = findReq(req.params.id);
  if (!r) return notFound(res, 'request');
  const items = db.requestItems.filter((i) => i.__ref.requestId === r.__ref.id);
  const folders = db.requestFolders.filter((i) => i.__ref.requestId === r.__ref.id);
  res.json({ ...r, collection: { items, folders } });
});
api.get('/requests/:id/parent-artifacts', (req, res) => {
  const r = findReq(req.params.id);
  if (!r) return notFound(res, 'request');
  const c = db.collections.find((x) => x.__ref.id === r.__ref.collectionId) || {};
  const f = r.__ref.folderId ? db.folders.find((x) => x.__ref.id === r.__ref.folderId) || {} : {};
  res.json({
    collection: { auth: c.auth, preScripts: c.preScripts || [], postScripts: c.postScripts || [] },
    folder: { auth: f.auth, preScripts: f.preScripts || [], postScripts: f.postScripts || [] },
  });
});
api.get('/requests/:id/collection', (req, res) => {
  const r = findReq(req.params.id);
  res.json({
    items: db.requestItems.filter((i) => i.__ref.requestId === req.params.id),
    folders: db.requestFolders.filter((i) => i.__ref.requestId === req.params.id),
    request: r,
  });
});
api.post('/requests', (req, res) => {
  const r = req.body || {};
  r.__ref = { ...(r.__ref || {}), id: r.__ref?.id || nid(), createdAt: now(), createdBy: db.currentUserId, updatedAt: now() };
  const { collection, ...clean } = r;
  db.requests.push(clean);
  attach(clean, 'rOrders');
  persist();
  res.json(clean);
});
api.put('/requests/:id', (req, res) => {
  const r = findReq(req.params.id);
  if (!r) return notFound(res, 'request');
  const b = req.body || {};
  const { __ref, __meta, collection, ...rest } = b.changes || b;
  Object.assign(r, rest);
  if (__meta) r.__meta = { ...r.__meta, ...__meta };
  r.__ref.updatedAt = now();
  r.__ref.updatedBy = db.currentUserId;
  persist();
  res.json(r);
});
api.delete('/requests/:id', (req, res) => {
  const r = findReq(req.params.id);
  if (r) detach(r, 'rOrders');
  db.requests = db.requests.filter((x) => x.__ref.id !== req.params.id);
  persist();
  res.json({ message: 'deleted' });
});
api.post('/requests/:id/move', (req, res) => {
  const r = findReq(req.params.id);
  if (r) {
    detach(r, 'rOrders');
    r.__ref.collectionId = req.body.collectionId || r.__ref.collectionId;
    r.__ref.folderId = req.body.folderId;
    attach(r, 'rOrders');
  }
  persist();
  res.json(r || {});
});
// request folders (websocket / socket.io / graphql saved items grouping)
api.get('/requests/:id/folders', (req, res) => res.json(db.requestFolders.filter((i) => i.__ref.requestId === req.params.id)));
api.post('/requests/:id/folders', (req, res) => {
  const f = { ...req.body, __ref: { ...(req.body.__ref || {}), id: req.body.__ref?.id || nid(), requestId: req.params.id, createdAt: now() } };
  db.requestFolders.push(f);
  persist();
  res.json(f);
});
api.put('/requests/:id/folders/:fid', (req, res) => {
  const f = db.requestFolders.find((x) => x.__ref.id === req.params.fid);
  if (f) Object.assign(f, { ...req.body, __ref: f.__ref });
  persist();
  res.json(f || {});
});
api.delete('/requests/:id/folders/:fid', (req, res) => {
  db.requestFolders = db.requestFolders.filter((x) => x.__ref.id !== req.params.fid);
  persist();
  res.json({ message: 'deleted' });
});
api.get('/requests/:id/items', (req, res) => res.json(db.requestItems.filter((i) => i.__ref.requestId === req.params.id)));
api.post('/requests/:id/items', (req, res) => {
  const i = { ...req.body, __ref: { ...(req.body.__ref || {}), id: req.body.__ref?.id || nid(), requestId: req.params.id, createdAt: now() } };
  db.requestItems.push(i);
  persist();
  res.json(i);
});
api.put('/requests/:id/items/:iid', (req, res) => {
  const i = db.requestItems.find((x) => x.__ref.id === req.params.iid);
  if (i) Object.assign(i, { ...req.body, __ref: i.__ref });
  persist();
  res.json(i || {});
});
api.delete('/requests/:id/items/:iid', (req, res) => {
  db.requestItems = db.requestItems.filter((x) => x.__ref.id !== req.params.iid);
  persist();
  res.json({ message: 'deleted' });
});

/* ------------------------------ environments ------------------------------ */
api.get('/environments', (req, res) => res.json(db.environments.filter((e) => e.__ref.workspaceId === req.headers['x-workspace-id'] || !req.headers['x-workspace-id'])));
api.get('/environments/:id/clone-from-beta', (req, res) => res.json({}));
api.get('/environments/:id', (req, res) => {
  const e = db.environments.find((x) => x.__ref.id === req.params.id);
  return e ? res.json(e) : notFound(res, 'environment');
});
api.post('/environments', (req, res) => {
  const e = { ...req.body, __ref: { ...(req.body.__ref || {}), id: req.body.__ref?.id || nid(), createdAt: now(), createdBy: db.currentUserId } };
  db.environments.push(e);
  persist();
  res.json(e);
});
api.put('/environments/:id', (req, res) => {
  const e = db.environments.find((x) => x.__ref.id === req.params.id);
  if (!e) return notFound(res, 'environment');
  const { __ref, ...rest } = req.body || {};
  Object.assign(e, rest);
  e.__ref.updatedAt = now();
  persist();
  res.json(e);
});
api.delete('/environments/:id', (req, res) => {
  db.environments = db.environments.filter((x) => x.__ref.id !== req.params.id);
  persist();
  res.json({ message: 'deleted' });
});

/* ------------------------------ collaboration (no-op) ------------------------------ */
api.all('/collaboration/*', (req, res) => res.json({}));
api.all('/sync/*', (req, res) => res.json({}));
api.all('*', (req, res) => res.json({}));

app.use('/api/v1', api);

/* ------------------------------ third-party assets (offline) ------------------------------ */
// The UI's stylesheets @import Google Fonts and the status bar shows a shields.io GitHub-stars badge.
// Those hosts are unreachable offline, so the built bundle is served with those URLs pointed here.
const FONTS_DIR = path.join(__dirname, '../fonts');
app.get('/__gfonts/css*', (req, res) => res.type('text/css').sendFile(path.join(FONTS_DIR, 'fonts.css')));
app.use('/__gfonts/files', express.static(FONTS_DIR, { maxAge: '7d' }));
// monaco-editor (normally loaded by @monaco-editor/loader from cdn.jsdelivr.net), vendored by fetch-assets.sh
app.use('/__cdn/monaco-editor@0.33.0/min', express.static(path.join(__dirname, '../monaco/min'), { maxAge: '7d' }));
// Crisp chat widget: no website id is configured, so serve an inert script instead of client.crisp.chat/l.js
app.get('/__stubs/crisp-l.js', (req, res) => res.type('application/javascript').send('/* crisp chat disabled offline */'));
app.get('/__badges/github-stars.svg', (req, res) =>
  res.type('image/svg+xml').send(
    `<svg xmlns="http://www.w3.org/2000/svg" width="140" height="28" role="img" aria-label="STAR US: 2.4K"><g shape-rendering="crispEdges"><rect width="89" height="28" fill="#555"/><rect x="89" width="51" height="28" fill="#ddd"/></g><g fill="#fff" text-anchor="middle" font-family="Verdana,Geneva,DejaVu Sans,sans-serif" font-size="10"><path fill="#fff" transform="translate(9 7) scale(0.6)" d="M12 .3a12 12 0 0 0-3.8 23.4c.6.1.8-.3.8-.6v-2c-3.3.7-4-1.6-4-1.6-.6-1.4-1.4-1.8-1.4-1.8-1-.7.1-.7.1-.7 1.2 0 1.9 1.2 1.9 1.2 1 1.8 2.8 1.3 3.5 1 0-.8.4-1.3.7-1.6-2.7-.3-5.5-1.3-5.5-6 0-1.2.5-2.3 1.3-3.1-.2-.4-.6-1.6 0-3.2 0 0 1-.3 3.4 1.2a11.5 11.5 0 0 1 6 0c2.3-1.5 3.3-1.2 3.3-1.2.6 1.6.2 2.8 0 3.2.9.8 1.3 1.9 1.3 3.2 0 4.6-2.8 5.6-5.5 5.9.5.4.9 1 .9 2.2v3.3c0 .3.1.7.8.6A12 12 0 0 0 12 .3"/><text x="54" y="18" font-weight="bold" letter-spacing="1">STAR US</text><text x="114" y="18" fill="#333" font-weight="bold" letter-spacing="1">2.4K</text></g></svg>`
  )
);
const rewriteCache = {};
app.get(/^\/[\w.-]+\.min\.js$/, (req, res, next) => {
  const file = path.join(STATIC_DIR, path.basename(req.path));
  if (!fs.existsSync(file)) return next();
  const stat = fs.statSync(file);
  const key = `${file}:${stat.mtimeMs}`;
  if (!rewriteCache[key]) {
    rewriteCache[key] = fs
      .readFileSync(file, 'utf8')
      .replace(/https:\/\/fonts\.googleapis\.com\/css2?/g, '/__gfonts/css')
      .replace(/https:\/\/cdn\.jsdelivr\.net\/npm\/monaco-editor@0\.33\.0\/min/g, '/__cdn/monaco-editor@0.33.0/min')
      .replace(/https:\/\/client\.crisp\.chat\/l\.js/g, '/__stubs/crisp-l.js')
      .replace(/https:\/\/img\.shields\.io\/github\/stars\/firecamp-dev\/firecamp[^"'`]*/g, '/__badges/github-stars.svg');
  }
  res.type('application/javascript').send(rewriteCache[key]);
});

/* ------------------------------ static UI ------------------------------ */
app.use(express.static(STATIC_DIR, { index: 'index.html' }));
app.get('*', (req, res) => res.sendFile(path.join(STATIC_DIR, 'index.html')));

const server = http.createServer(app);
const io = new Server(server, { cors: { origin: true, credentials: true } });
io.on('connection', (socket) => {
  socket.emit('workspace', { type: 'connected' });
});

server.listen(PORT, () => console.log(`Firecamp (local stub API + UI) on http://localhost:${PORT}/`));
